"""Text-to-SQL harness: draft query, execute it, and spend the second policy
call on a semantics-aware repair turn when the draft errors, looks cut off, or
returns an empty result whose literals do not exist in the database.

Contract (fixed): solve(task, env) -> {"sql": str}
"""

import re

SQL_BLOCK = re.compile(r"```(?:sql|sqlite)?\s*(.*?)```", re.S | re.I)
START_KW = re.compile(r"^\s*(WITH|SELECT)\b", re.I)
LITERAL = re.compile(r"'([^']{1,60})'")
IDENT = re.compile(r"[A-Za-z_][A-Za-z_0-9]*")


def extract_sql(text):
    text = text or ""
    blocks = [b.strip() for b in SQL_BLOCK.findall(text) if b.strip()]
    if blocks:
        return blocks[-1].rstrip(";").strip()
    m = re.search(r"```(?:sql|sqlite)?\s*(.*)$", text, re.S | re.I)
    if m and START_KW.match(m.group(1)):
        return m.group(1).strip().rstrip(";").strip()
    m = re.search(r"(?:^|\n)\s*(WITH|SELECT)\b", text, re.I)
    if m:
        return text[m.start():].strip().rstrip(";").strip()
    return text.strip().rstrip(";").strip()


def looks_truncated(sql):
    if not sql:
        return True
    if sql.count("(") != sql.count(")"):
        return True
    if sql.count("'") % 2 == 1 or sql.count('"') % 2 == 1:
        return True
    if re.search(r"\b(SELECT|FROM|WHERE|AND|OR|BY|ON|JOIN|HAVING|LIMIT|AS|IN|LIKE|=|<|>|,)\s*$", sql, re.I):
        return True
    return False


def build_user(task, env):
    user = f"Database: {task['db_id']}\n\nSchema:\n{env.schema(task['db_id'])}"
    desc = ""
    try:
        desc = env.descriptions(task["db_id"]) or ""
    except Exception:
        desc = ""
    if desc.strip():
        user += f"\n\nColumn descriptions:\n{desc.strip()[:4000]}"
    user += f"\n\nQuestion: {task['question']}"
    if task.get("hint"):
        user += f"\nHint: {task['hint']}"
    return user


def _tables_columns(schema_text):
    """Parse CREATE TABLE statements into {table: [columns]} (best effort)."""
    out = {}
    for m in re.finditer(r"CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?[\"'`\[]?(\w+)[\"'`\]]?\s*\((.*?)\)\s*;",
                         schema_text or "", re.S | re.I):
        name, body = m.group(1), m.group(2)
        cols = []
        depth = 0
        cur = ""
        parts = []
        for ch in body:
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
            if ch == "," and depth == 0:
                parts.append(cur)
                cur = ""
            else:
                cur += ch
        parts.append(cur)
        skip = {"primary", "foreign", "unique", "check", "constraint", "key"}
        for p in parts:
            t = p.strip().lstrip("\"'`[")
            w = IDENT.match(t)
            if w and w.group(0).lower() not in skip:
                cols.append(w.group(0))
        out[name] = cols
    return out


def literals_present(sql, env, db_id):
    """Check whether the string literals used in the query occur in the tables
    the query touches. Returns (missing_literals, checked_any)."""
    lits = [s for s in LITERAL.findall(sql or "") if s.strip() and not s.startswith("%")]
    if not lits:
        return [], False
    try:
        schema_text = env.schema(db_id)
    except Exception:
        return [], False
    tc = _tables_columns(schema_text)
    used = set(IDENT.findall(sql or ""))
    tables = [t for t in tc if t in used]
    if not tables:
        return [], False
    found = set()
    checked = False
    for lit in lits[:4]:
        esc = lit.replace("'", "''")
        for t in tables[:4]:
            for c in tc[t][:25]:
                q = f'SELECT 1 FROM "{t}" WHERE CAST("{c}" AS TEXT) = \'{esc}\' LIMIT 1'
                try:
                    r = env.execute(q, max_rows=1)
                except Exception:
                    continue
                if not r or not r.get("ok"):
                    continue
                checked = True
                if r.get("n_rows", 0) > 0:
                    found.add(lit)
                    break
            if lit in found:
                break
    missing = [l for l in lits[:4] if l not in found] if checked else []
    return missing, checked


def repair_message(task, sql, res, truncated, extra=""):
    lines = [f"Question (re-read it carefully): {task['question']}"]
    if task.get("hint"):
        lines.append(f"Hint: {task['hint']}")
    lines += ["Your previous draft was:", "```sql", sql, "```"]
    if truncated:
        lines.append("It appears incomplete or malformed (cut off mid-statement). Rewrite it as one short, complete query.")
    if res is None:
        lines.append("It could not be executed.")
    elif not res.get("ok"):
        lines.append(f"Execution FAILED with error: {res.get('error')}")
        lines.append("Fix the syntax or the table/column names (use only names present in the schema).")
    elif res.get("n_rows", 0) == 0:
        lines.append("It executed successfully but returned 0 rows.")
        lines.append(
            "Zero rows may be correct, but first check for a concrete mistake: a string literal that does not match "
            "stored values (case, spacing, abbreviation, suffix), the wrong column, or a wrong join key. "
            "You may probe with SELECT DISTINCT <column> FROM <table> LIMIT 20. "
            "Do NOT drop or loosen a condition just to obtain rows."
        )
    else:
        lines.append(f"It returned {res.get('n_rows')} rows; columns: {res.get('columns')}.")
        lines.append(f"First rows: {str(res.get('rows'))[:600]}")
        lines.append(
            "Check the result against the question:\n"
            "1. Projection: exactly the requested columns; if the question asks WHICH entities without naming "
            "attributes, the answer should be the full rows of the main entity table (T1.*).\n"
            "2. Duplicates: repeated identical entity rows mean a one-to-many join fanned out; use EXISTS/IN instead.\n"
            "3. Aggregates: SUM/AVG/COUNT over an entity attribute must not be inflated by a one-to-many join; "
            "restrict with IN/EXISTS. For 'most X per Y', group by the entity id and order by COUNT(*) DESC.\n"
            "4. Negation: 'do not / not / never' must exclude the whole entity via NOT IN / NOT EXISTS over the "
            "positive condition, not a row-level != or flag='F' filter.\n"
            "5. Comparisons: 'than any' vs 'than all' map to MAX/MIN subqueries as specified."
        )
    if extra:
        lines.append(extra)
    lines.append(
        "Reply with ONLY the final query in a single ```sql code block. "
        "If the draft is already correct, repeat it unchanged."
    )
    return "\n".join(lines)


def solve(task, env):
    max_tokens = env.config.get("max_tokens", 800)
    messages = [
        {"role": "system", "content": env.prompt("system_prompt.md")},
        {"role": "user", "content": build_user(task, env)},
    ]
    reply = env.chat(messages, max_tokens=max_tokens)
    sql = extract_sql(reply)

    truncated = looks_truncated(sql)
    res = None
    try:
        res = env.execute(sql, max_rows=20)
    except Exception:
        res = None

    ok = res is not None and res.get("ok")
    empty = ok and res.get("n_rows", 0) == 0

    extra = ""
    need_repair = truncated or not ok
    if empty and not truncated:
        # An empty answer is often correct. Only spend the second call when we
        # have local evidence that a filter literal does not exist in the data.
        missing, checked = literals_present(sql, env, task["db_id"])
        if checked and missing:
            need_repair = True
            extra = ("Local check: these literal values were NOT found in any column of the tables used: "
                     + ", ".join(repr(m) for m in missing)
                     + ". Probe the real stored values and use the exact ones, or reconsider which column to filter.")
        elif not checked:
            need_repair = True
    if not need_repair:
        return {"sql": sql}

    messages.append({"role": "assistant", "content": reply})
    messages.append({"role": "user", "content": repair_message(task, sql, res, truncated, extra)})
    try:
        reply2 = env.chat(messages, max_tokens=max_tokens)
    except Exception:
        return {"sql": sql}
    sql2 = extract_sql(reply2)
    if not sql2:
        return {"sql": sql}

    res2 = None
    try:
        res2 = env.execute(sql2, max_rows=20)
    except Exception:
        res2 = None

    def usable(r):
        return r is not None and r.get("ok")

    if looks_truncated(sql2) and not truncated:
        return {"sql": sql}
    if usable(res2) or not usable(res):
        return {"sql": sql2}
    return {"sql": sql}

